    return name && name !== '苏州' && region.indexOf(name) >= 0
  })
  if (hit) this.$emit('district-change', hit.value)
}

tool_input.new_string:
regionFromParams(params) {
  const raw = params.data && (params.data.raw || this.points.find((p) => p.name === params.data.name))
  if (raw && raw.region) return String(raw.region)
  if (params.name) return String(params.name)
  return ''
},
onClick(params) {
  const region = this.regionFromParams(params)
  if (!region) return
  const hit = this.tabList.find((d) => {
    const name = String(d.name || '').replace(/[（(].*$/, '').replace(/市|区|县/g, '')
    return name && name !== '苏州' && region.indexOf(name) >= 0
  })
  if (hit) this.$emit('district-change', hit.value)
}

